{
  "title": "All UI Controls",
  "description": "Every input below is bound to a notebook variable and saved in notebook.state.",
  "controls": [
    {
      "type": "label",
      "label": "Read-only label",
      "text": "Labels add instructions or section text inside a UI cell."
    },
    {
      "type": "text",
      "label": "Text input",
      "bind": "demo_name",
      "default": "Ada",
      "placeholder": "Type a name"
    },
    {
      "type": "textarea",
      "label": "Textarea",
      "bind": "demo_notes",
      "default": "Try changing these controls, then run the cells below.",
      "rows": 4
    },
    {
      "type": "number",
      "label": "Number input",
      "bind": "demo_count",
      "default": 12,
      "min": 0,
      "max": 100,
      "step": 1
    },
    {
      "type": "checkbox",
      "label": "Checkbox toggle",
      "bind": "demo_enabled",
      "default": true
    },
    {
      "type": "select",
      "label": "Dropdown select",
      "bind": "demo_mode",
      "default": "balanced",
      "options": [
        {
          "label": "Fast",
          "value": "fast"
        },
        {
          "label": "Balanced",
          "value": "balanced"
        },
        {
          "label": "Careful",
          "value": "careful"
        }
      ]
    },
    {
      "type": "radio",
      "label": "Radio options",
      "bind": "demo_priority",
      "default": "medium",
      "options": [
        "low",
        "medium",
        "high"
      ]
    },
    {
      "type": "slider",
      "label": "Slider",
      "bind": "demo_volume",
      "default": 65,
      "min": 0,
      "max": 100,
      "step": 5
    },
    {
      "type": "color",
      "label": "Color picker",
      "bind": "demo_color",
      "default": "#7c3aed"
    },
    {
      "type": "date",
      "label": "Date input",
      "bind": "demo_due",
      "default": "2026-04-24"
    },
    {
      "type": "button",
      "label": "Press action button",
      "icon": "fa-bolt",
      "set": {
        "demo_button_clicked": true,
        "demo_button_message": "The UI button updated notebook state."
      }
    }
  ]
}
